export function translate(language: Language, russian: string, english: string): string {
  if (language === "ru") return russian;
  if (language === "de") return germanTranslations[english] ?? english;
  return english;
}

export type Translator = (russian: string, english: string) => string;

/** Binds translate() to one language, for components that render many strings. */
export function makeT(language: Language): Translator {
  return (russian, english) => translate(language, russian, english);
}

/** Kilometre values with a localized unit label. */
export function formatKm(value: number | string, language: Language): string {
  return `${value} ${language === "ru" ? "км" : "km"}`;
}
